from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        sz = n * m

        # Flatten grid for speed.
        g = [0] * sz
        for i in range(n):
            row = grid[i]
            base = i * m
            for j in range(m):
                g[base + j] = row[j]

        # next value in the sequence 1,2,0,2,0,...
        # 1->2, 2->0, 0->2
        nxt = (2, 2, 0)

        # Directions: 0=DR (1,1), 1=DL (1,-1), 2=UL (-1,-1), 3=UR (-1,1)
        # R[d][idx] = longest alternating straight segment STARTING at idx going d.
        R0 = [1] * sz
        R1 = [1] * sz
        R2 = [1] * sz
        R3 = [1] * sz

        # R0 DR: successor (i+1, j+1)
        for i in range(n - 1, -1, -1):
            base = i * m
            for j in range(m - 1, -1, -1):
                idx = base + j
                if i + 1 < n and j + 1 < m:
                    q = idx + m + 1
                    if g[q] == nxt[g[idx]]:
                        R0[idx] = R0[q] + 1
        # R1 DL: successor (i+1, j-1)
        for i in range(n - 1, -1, -1):
            base = i * m
            for j in range(m):
                idx = base + j
                if i + 1 < n and j > 0:
                    q = idx + m - 1
                    if g[q] == nxt[g[idx]]:
                        R1[idx] = R1[q] + 1
        # R2 UL: successor (i-1, j-1)
        for i in range(n):
            base = i * m
            for j in range(m):
                idx = base + j
                if i > 0 and j > 0:
                    q = idx - m - 1
                    if g[q] == nxt[g[idx]]:
                        R2[idx] = R2[q] + 1
        # R3 UR: successor (i-1, j+1)
        for i in range(n):
            base = i * m
            for j in range(m - 1, -1, -1):
                idx = base + j
                if i > 0 and j + 1 < m:
                    q = idx - m + 1
                    if g[q] == nxt[g[idx]]:
                        R3[idx] = R3[q] + 1

        # Length-1 segment is any cell holding 1.
        ans = 1 if 1 in g else 0

        # f[d][idx] = longest alternating straight segment ENDING at idx whose
        # last move was in direction d (must start at a value 1).
        # At a turn vertex, combine first arm (direction d) with second arm
        # (clockwise direction (d+1)%4): total = f + R[(d+1)%4] - 1.
        # Since R >= 1, this also covers zero-turn straight segments.

        # d = 0 (DR), predecessor (i-1,j-1), clockwise -> DL (R1)
        f = [0] * sz
        Rc = R1
        for i in range(n):
            base = i * m
            for j in range(m):
                idx = base + j
                best = 0
                if i > 0 and j > 0:
                    p = idx - m - 1
                    fo = f[p]
                    if fo == 0:
                        fo = 1 if g[p] == 1 else 0
                    if fo and g[idx] == nxt[g[p]]:
                        best = fo + 1
                f[idx] = best
                if best:
                    tot = best + Rc[idx] - 1
                    if tot > ans: ans = tot

        # d = 1 (DL), predecessor (i-1,j+1), clockwise -> UL (R2)
        f = [0] * sz
        Rc = R2
        for i in range(n):
            base = i * m
            for j in range(m - 1, -1, -1):
                idx = base + j
                best = 0
                if i > 0 and j + 1 < m:
                    p = idx - m + 1
                    fo = f[p]
                    if fo == 0:
                        fo = 1 if g[p] == 1 else 0
                    if fo and g[idx] == nxt[g[p]]:
                        best = fo + 1
                f[idx] = best
                if best:
                    tot = best + Rc[idx] - 1
                    if tot > ans: ans = tot

        # d = 2 (UL), predecessor (i+1,j+1), clockwise -> UR (R3)
        f = [0] * sz
        Rc = R3
        for i in range(n - 1, -1, -1):
            base = i * m
            for j in range(m - 1, -1, -1):
                idx = base + j
                best = 0
                if i + 1 < n and j + 1 < m:
                    p = idx + m + 1
                    fo = f[p]
                    if fo == 0:
                        fo = 1 if g[p] == 1 else 0
                    if fo and g[idx] == nxt[g[p]]:
                        best = fo + 1
                f[idx] = best
                if best:
                    tot = best + Rc[idx] - 1
                    if tot > ans: ans = tot

        # d = 3 (UR), predecessor (i+1,j-1), clockwise -> DR (R0)
        f = [0] * sz
        Rc = R0
        for i in range(n - 1, -1, -1):
            base = i * m
            for j in range(m):
                idx = base + j
                best = 0
                if i + 1 < n and j > 0:
                    p = idx + m - 1
                    fo = f[p]
                    if fo == 0:
                        fo = 1 if g[p] == 1 else 0
                    if fo and g[idx] == nxt[g[p]]:
                        best = fo + 1
                f[idx] = best
                if best:
                    tot = best + Rc[idx] - 1
                    if tot > ans: ans = tot

        return ans

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        A, B, C = p.split('*')          # exactly two '*', so exactly three parts
        INF = float('inf')

        # KMP: return start indices of all (overlapping) occurrences of pat in text
        def kmp_occ(text, pat):
            m = len(pat)
            lps = [0] * m
            k = 0
            for i in range(1, m):
                c = pat[i]
                while k and c != pat[k]:
                    k = lps[k - 1]
                if c == pat[k]:
                    k += 1
                    lps[i] = k
            occ = []
            j = 0
            for i, c in enumerate(text):
                while j and c != pat[j]:
                    j = lps[j - 1]
                if c == pat[j]:
                    j += 1
                if j == m:
                    occ.append(i - m + 1)
                    j = lps[j - 1]
            return occ

        lenA, lenB, lenC = len(A), len(B), len(C)

        # nextB[i] = smallest start >= i of an occurrence of B (INF if none)
        if B:
            nxtB = [INF] * (n + 2)
            for o in kmp_occ(s, B):
                nxtB[o] = o
            for i in range(n, -1, -1):
                if nxtB[i + 1] < nxtB[i]:
                    nxtB[i] = nxtB[i + 1]
        else:
            nxtB = None   # empty B "occurs" at every position i, handled inline

        if C:
            nxtC = [INF] * (n + 2)
            for o in kmp_occ(s, C):
                nxtC[o] = o
            for i in range(n, -1, -1):
                if nxtC[i + 1] < nxtC[i]:
                    nxtC[i] = nxtC[i + 1]
        else:
            nxtC = None

        starts = kmp_occ(s, A) if A else range(n + 1)
        best = -1
        for l in starts:
            p1 = l + lenA                 # position right after A (end of first star)
            if p1 > n:
                continue
            if nxtB is not None:
                b = nxtB[p1]
                if b == INF:
                    continue
            else:
                b = p1                    # B empty, place it at p1
            p2 = b + lenB                 # position right after B
            if p2 > n:
                continue
            if nxtC is not None:
                c = nxtC[p2]
                if c == INF:
                    continue
            else:
                c = p2                    # C empty, place it at p2
            length = c + lenC - l
            if best < 0 or length < best:
                best = length
        return best

class Solution:
    def countSubstrings(self, s: str) -> int:
        digits = [ord(ch) - 48 for ch in s]
        present = [False] * 10
        for c in digits:
            present[c] = True

        ans = 0
        for d in range(1, 10):
            if not present[d]:
                continue
            # trans[c][r] = residue after appending digit c to a value with residue r (mod d)
            trans = [[(r * 10 + c) % d for r in range(d)] for c in range(10)]
            cnt = [0] * d  # substrings ending at previous index, by residue mod d
            for c in digits:
                tr = trans[c]
                nc = [0] * d
                for r, v in enumerate(cnt):
                    if v:
                        nc[tr[r]] += v
                nc[c % d] += 1  # length-1 substring ending here
                if c == d:
                    ans += nc[0]
                cnt = nc
        return ans

