from typing import List

class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(nums)
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        max_val = max(nums)
        last = [-1] * (max_val + 1)
        path_dist = [0] * n

        best_len = 0
        best_cnt = 1

        stack = [(0, -1, 0, 0, 0, False, -1)]
        while stack:
            v, p, dep, d, parent_ns, entered, prev = stack.pop()
            x = nums[v]
            if not entered:
                ns = parent_ns
                if last[x] != -1:
                    cand = last[x] + 1
                    if cand > ns:
                        ns = cand
                    prev = last[x]
                else:
                    prev = -1
                last[x] = dep
                path_dist[dep] = d

                length = d - path_dist[ns]
                cnt = dep - ns + 1
                if length > best_len or (length == best_len and cnt < best_cnt):
                    best_len = length
                    best_cnt = cnt

                stack.append((v, p, dep, d, ns, True, prev))
                for to, w in adj[v]:
                    if to != p:
                        stack.append((to, v, dep + 1, d + w, ns, False, -1))
            else:
                last[x] = prev

        return [best_len, best_cnt]

import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    P = int(data[1])
    H = N // 2
    D = N * (N - 1) // 2

    # factorials up to D
    fact = [1] * (D + 1)
    for i in range(1, D + 1):
        fact[i] = fact[i-1] * i % P
    invfact = [1] * (D + 1)
    invfact[D] = pow(fact[D], P - 2, P)
    for i in range(D, 0, -1):
        invfact[i-1] = invfact[i] * i % P

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * invfact[k] % P * invfact[n-k] % P

    # index for DP state (E, O, s, p)
    def idx(E, O, s, p):
        return ((E * (H + 1) + O) * (N + 1) + s) * 2 + p

    S = (H + 1) * (H + 1) * (N + 1) * 2

    # precompute all valid transitions grouped by total used vertices t
    states_by_t = [[] for _ in range(N)]  # t = 1 .. N-1
    for t in range(1, N):
        E_start = max(0, t - H)
        E_end = min(H, t)
        for E in range(E_start, E_end + 1):
            O = t - E
            for s in range(1, t + 1):
                for p in (0, 1):
                    if p == 0 and s > E:
                        continue
                    if p == 1 and s > O:
                        continue
                    state_idx = idx(E, O, s, p)
                    q = 1 - p
                    if q == 1:
                        rem = H - O
                    else:
                        rem = H - E
                    if rem == 0:
                        continue
                    trans = []
                    for b in range(1, rem + 1):
                        newE = E + (b if q == 0 else 0)
                        newO = O + (b if q == 1 else 0)
                        newS = b
                        newP = q
                        new_idx = idx(newE, newO, newS, newP)
                        c = C(rem, b)
                        trans.append((new_idx, c, b, s))
                    if trans:
                        states_by_t[t].append((state_idx, trans))

    # small binomial coefficients for cover computation
    comb_small = [[0] * (N + 1) for _ in range(N + 1)]
    for b in range(N + 1):
        for i in range(b + 1):
            comb_small[b][i] = C(b, i)

    y = [0] * (D + 1)
    start_idx = idx(1, 0, 1, 0)
    final_indices = [idx(H, H, s, p) for s in range(1, N + 1) for p in (0, 1)]

    for x in range(D + 1):
        base = (1 + x) % P
        w = [1] * (D + 1)
        wk = 1
        for k in range(1, D + 1):
            wk = wk * base % P
            w[k] = wk

        I = [1] * (N + 1)
        for b in range(2, N + 1):
            I[b] = w[b * (b - 1) // 2]

        # cover_w[s][b] = (number of ways to connect level of size s to size b covering all b) * (1+x)^{C(b,2)}
        cover_w = [[0] * (N + 1) for _ in range(N + 1)]
        for s in range(1, N + 1):
            for b in range(1, N - s + 1):
                total = 0
                for i in range(b + 1):
                    term = comb_small[b][i] * w[s * i] % P
                    if (b - i) & 1:
                        total -= term
                    else:
                        total += term
                cover_w[s][b] = (total % P) * I[b] % P

        dp = [0] * S
        dp[start_idx] = 1
        for t in range(1, N):
            for state_idx, trans in states_by_t[t]:
                val = dp[state_idx]
                if val == 0:
                    continue
                for new_idx, c, b, s in trans:
                    wgt = c * cover_w[s][b] % P
                    dp[new_idx] = (dp[new_idx] + val * wgt) % P

        res = 0
        for fi in final_indices:
            res += dp[fi]
        y[x] = res % P

    # Lagrange interpolation to recover coefficients a[0..D]
    poly = [1]
    for j in range(D + 1):
        new_poly = [0] * (len(poly) + 1)
        for i, coeff in enumerate(poly):
            new_poly[i] = (new_poly[i] - j * coeff) % P
            new_poly[i + 1] = (new_poly[i + 1] + coeff) % P
        poly = new_poly

    a = [0] * (D + 1)
    for i in range(D + 1):
        Q = [0] * (D + 1)
        Q[D] = 1
        for k in range(D, 0, -1):
            Q[k - 1] = (poly[k] + i * Q[k]) % P
        denom = fact[i] * fact[D - i] % P
        if (D - i) & 1:
            denom = (-denom) % P
        inv_denom = pow(denom, P - 2, P)
        factor = y[i] * inv_denom % P
        for k in range(D + 1):
            a[k] = (a[k] + factor * Q[k]) % P

    comb_part = C(N - 1, H)
    out = []
    for M in range(N - 1, D + 1):
        out.append(str(a[M] * comb_part % P))
    print(" ".join(out))

if __name__ == "__main__":
    main()

import sys

def main():
    data = sys.stdin.buffer.read().split()
    pos = 0
    N = int(data[pos]); pos += 1
    p = int(data[pos]); pos += 1
    A = []
    for _ in range(N):
        row = list(map(int, data[pos:pos + N]))
        pos += N
        A.append(row)

    K = 0
    for i in range(N):
        Ai = A[i]
        for j in range(N):
            if Ai[j] == 0:
                K += 1

    # p = 2: only nonzero value is 1, so the unique completion is the all-ones
    # matrix J, and J^2 = N*J  =>  every entry is N mod 2.
    if p == 2:
        v = N & 1
        line = ' '.join([str(v)] * N)
        sys.stdout.write('\n'.join([line] * N) + '\n')
        return

    def compute_power():
        """Return C^p mod p as a list of lists, where C = A (zeros kept as 0)."""
        try:
            import numpy as np
        except Exception:
            np = None

        if np is not None:
            Anp = np.array(A, dtype=np.int64) % p
            shift = (1 << 15) % p

            def matmul(X, Y):
                Y1 = Y >> 15
                Y0 = Y & 32767
                t1 = (X @ Y1) % p
                t0 = (X @ Y0) % p
                return (t1 * shift + t0) % p

            result = np.eye(N, dtype=np.int64) % p
            base = Anp.copy()
            e = p
            while e > 0:
                if e & 1:
                    result = matmul(result, base)
                e >>= 1
                if e:
                    base = matmul(base, base)
            return result.tolist()
        else:
            def matmul(X, Y):
                n = len(X)
                Z = [[0] * n for _ in range(n)]
                for i in range(n):
                    Xi = X[i]
                    Zi = Z[i]
                    for k in range(n):
                        a = Xi[k]
                        if a:
                            Yk = Y[k]
                            for j in range(n):
                                Zi[j] += a * Yk[j]
                    for j in range(n):
                        Zi[j] %= p
                return Z

            result = [[1 if i == j else 0 for j in range(N)] for i in range(N)]
            base = [row[:] for row in A]
            e = p
            while e > 0:
                if e & 1:
                    result = matmul(result, base)
                e >>= 1
                if e:
                    base = matmul(base, base)
            return result

    M = compute_power()

    # Corrections for walks that use exactly one zero-variable p-1 times
    # (the only surviving monomials besides all-constant walks).
    if p == 3:
        # A variable used twice; the remaining step may bridge the two uses.
        for u in range(N):
            for v in range(N):
                if A[u][v] == 0:
                    if u == v:
                        # loop-then-leave (row u) and enter-then-loop (column u)
                        for j in range(N):
                            M[u][j] = (M[u][j] + A[u][j]) % p
                            M[j][u] = (M[j][u] + A[j][u]) % p
                    else:
                        # u ->v (var) v->u (const) u->v (var)
                        M[u][v] = (M[u][v] + A[v][u]) % p
    else:
        # p >= 5: only diagonal zeros can be used p-1 times, always as a loop,
        # with the single constant edge at the very start or very end.
        for u in range(N):
            if A[u][u] == 0:
                for j in range(N):
                    M[u][j] = (M[u][j] + A[u][j]) % p   # leave after loops
                    M[j][u] = (M[j][u] + A[j][u]) % p   # enter before loops

    # Every zero variable contributes sum_{x in F_p^*} x^e = -1 when (p-1)|e.
    sign = pow(p - 1, K, p)
    if sign != 1:
        for i in range(N):
            Mi = M[i]
            for j in range(N):
                Mi[j] = Mi[j] * sign % p

    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in M) + '\n')

main()

import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    ptr = 0
    N = int(data[ptr]); ptr += 1
    M = int(data[ptr]); ptr += 1
    A = int(data[ptr]); ptr += 1
    B = int(data[ptr]); ptr += 1

    # Merge adjacent (or touching) bad intervals into maximal bad blocks.
    blocks = []
    for _ in range(M):
        L = int(data[ptr]); ptr += 1
        R = int(data[ptr]); ptr += 1
        if blocks and L <= blocks[-1][1] + 1:
            if R > blocks[-1][1]:
                blocks[-1] = (blocks[-1][0], R)
        else:
            blocks.append((L, R))

    # Case A == B: fixed step, reachable squares are 1, 1+A, 1+2A, ...
    if A == B:
        if (N - 1) % A != 0:
            sys.stdout.write("No\n")
            return
        for L, R in blocks:
            x = L + ((1 - L) % A)   # smallest x >= L with x % A == 1
            if x <= R:
                sys.stdout.write("No\n")
                return
        sys.stdout.write("Yes\n")
        return

    # Case A < B.
    # A bad block of length >= B can never be jumped over.
    for L, R in blocks:
        if R - L + 1 >= B:
            sys.stdout.write("No\n")
            return

    full = (1 << B) - 1
    # bits A-1..B-1 : predecessors within allowed jump range
    maskA = ((1 << (B - A + 1)) - 1) << (A - 1)
    # If a good run is at least THRESH long, reachability saturates to all-ones
    # (from one reachable t, increments A and A+1 make all t+s, s >= A^2-A, reachable;
    #  first reachable t in a run is within B of its start).
    THRESH = A * A + 2 * B + 5

    reach = 1          # bit j = dp[current_pos - j]; start at position 1
    cur_pos = 2        # next position to process
    ok = True

    for L, R in blocks:
        # ---- good run [cur_pos, L-1] ----
        if cur_pos <= L - 1:
            if reach == 0:
                ok = False
                break
            length = (L - 1) - cur_pos + 1
            if length >= THRESH:
                reach = full
            else:
                cur = reach
                m = maskA
                f = full
                for _ in range(length):
                    if cur == f:
                        break
                    if cur & m:
                        cur = ((cur << 1) | 1) & f
                    else:
                        cur = (cur << 1) & f
                reach = cur
        # ---- bad block [L, R] : all zeros, just shift ----
        blen = R - L + 1
        reach = (reach << blen) & full
        cur_pos = R + 1
        if reach == 0:
            ok = False
            break

    # ---- trailing good run [cur_pos, N] ----
    if ok and cur_pos <= N:
        if reach == 0:
            ok = False
        else:
            length = N - cur_pos + 1
            if length >= THRESH:
                reach = full
            else:
                cur = reach
                m = maskA
                f = full
                for _ in range(length):
                    if cur == f:
                        break
                    if cur & m:
                        cur = ((cur << 1) | 1) & f
                    else:
                        cur = (cur << 1) & f
                reach = cur

    sys.stdout.write("Yes\n" if (ok and (reach & 1)) else "No\n")

main()

