import sys
from collections import deque

def main():
    MOD = 998244353
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M = data[0], data[1]
    A = [0] + data[2:2 + N]

    indeg = [0] * (N + 1)
    for i in range(1, N + 1):
        indeg[A[i]] += 1

    q = deque(i for i in range(1, N + 1) if indeg[i] == 0)
    removed = []
    is_cycle = [True] * (N + 1)

    while q:
        u = q.popleft()
        removed.append(u)
        is_cycle[u] = False
        v = A[u]
        indeg[v] -= 1
        if indeg[v] == 0:
            q.append(v)

    acc = [None] * (N + 1)

    for u in removed:
        arr = acc[u]
        p = A[u]
        ap = acc[p]

        if ap is None:
            if arr is None:
                acc[p] = list(range(M + 1))
            else:
                pref = [0] * (M + 1)
                s = 0
                for t in range(1, M + 1):
                    s += arr[t]
                    if s >= MOD:
                        s -= MOD
                    pref[t] = s
                acc[p] = pref
        else:
            if arr is None:
                for t in range(1, M + 1):
                    ap[t] = (ap[t] * t) % MOD
            else:
                s = 0
                for t in range(1, M + 1):
                    s += arr[t]
                    if s >= MOD:
                        s -= MOD
                    ap[t] = (ap[t] * s) % MOD

        acc[u] = None

    ans = 1
    visited = [False] * (N + 1)

    for i in range(1, N + 1):
        if is_cycle[i] and not visited[i]:
            cyc = []
            v = i
            while not visited[v]:
                visited[v] = True
                cyc.append(v)
                v = A[v]

            prod = None
            for v in cyc:
                arr = acc[v]
                if arr is not None:
                    if prod is None:
                        prod = arr
                        acc[v] = None
                    else:
                        for t in range(1, M + 1):
                            prod[t] = (prod[t] * arr[t]) % MOD
                        acc[v] = None

            if prod is None:
                cycle_sum = M % MOD
            else:
                cycle_sum = sum(prod[1:]) % MOD

            ans = (ans * cycle_sum) % MOD

    print(ans)

if __name__ == "__main__":
    main()

class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        if k < 0 or k > n - 1:
            return 0

        N = n - 1

        fact = [1] * (N + 1)
        for i in range(1, N + 1):
            fact[i] = fact[i - 1] * i % MOD

        inv_fact = [1] * (N + 1)
        inv_fact[N] = pow(fact[N], MOD - 2, MOD)
        for i in range(N, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        choose = fact[N] * inv_fact[k] % MOD * inv_fact[N - k] % MOD
        return choose * m % MOD * pow(m - 1, N - k, MOD) % MOD

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        # Collect maximal run lengths of the original string.
        runs = []
        cur = 1
        for i in range(1, n):
            if s[i] == s[i - 1]:
                cur += 1
            else:
                runs.append(cur)
                cur = 1
        runs.append(cur)

        max_run = max(runs)
        if max_run == 1:
            return 1  # already alternating (also covers n == 1)

        # Min flips to reach a fully alternating string = min Hamming distance
        # to "0101..." and to its complement "1010...".
        d0 = 0
        for i, ch in enumerate(s):
            cbit = 1 if ch == '1' else 0
            if cbit != (i & 1):     # pattern P0 has bit == i % 2
                d0 += 1
        min_alt = min(d0, n - d0)

        def can(L: int) -> bool:
            if L == 1:
                return min_alt <= numOps
            total = 0
            for r in runs:
                total += r // (L + 1)   # flips needed to break this run
                if total > numOps:
                    return False
            return True

        lo, hi = 1, max_run
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

import sys
from bisect import bisect_right

def main():
    data = sys.stdin.buffer.read().split()
    pos = 0
    N = int(data[pos]); pos += 1
    M = int(data[pos]); pos += 1
    cx = int(data[pos]); pos += 1
    cy = int(data[pos]); pos += 1

    by_y = {}
    by_x = {}
    for i in range(N):
        x = int(data[pos]); pos += 1
        y = int(data[pos]); pos += 1
        by_y.setdefault(y, []).append((x, i))
        by_x.setdefault(x, []).append((y, i))

    h_intervals = {}
    v_intervals = {}
    for _ in range(M):
        d = data[pos]; pos += 1
        c = int(data[pos]); pos += 1
        if d == b'U':
            v_intervals.setdefault(cx, []).append((cy, cy + c))
            cy += c
        elif d == b'D':
            v_intervals.setdefault(cx, []).append((cy - c, cy))
            cy -= c
        elif d == b'L':
            h_intervals.setdefault(cy, []).append((cx - c, cx))
            cx -= c
        else:  # R
            h_intervals.setdefault(cy, []).append((cx, cx + c))
            cx += c

    covered = bytearray(N)

    # Horizontal coverage: houses grouped by y, intervals on x at fixed y
    for y, ivs in h_intervals.items():
        houses = by_y.get(y)
        if not houses:
            continue
        ivs.sort()
        starts = []
        ends = []
        clo, chi = ivs[0]
        for lo, hi in ivs[1:]:
            if lo <= chi:
                if hi > chi:
                    chi = hi
            else:
                starts.append(clo); ends.append(chi)
                clo, chi = lo, hi
        starts.append(clo); ends.append(chi)
        for x, idx in houses:
            j = bisect_right(starts, x) - 1
            if j >= 0 and x <= ends[j]:
                covered[idx] = 1

    # Vertical coverage: houses grouped by x, intervals on y at fixed x
    for x, ivs in v_intervals.items():
        houses = by_x.get(x)
        if not houses:
            continue
        ivs.sort()
        starts = []
        ends = []
        clo, chi = ivs[0]
        for lo, hi in ivs[1:]:
            if lo <= chi:
                if hi > chi:
                    chi = hi
            else:
                starts.append(clo); ends.append(chi)
                clo, chi = lo, hi
        starts.append(clo); ends.append(chi)
        for y, idx in houses:
            j = bisect_right(starts, y) - 1
            if j >= 0 and y <= ends[j]:
                covered[idx] = 1

    print(cx, cy, sum(covered))

main()

import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    n = next(it)

    adj = [[] for _ in range(n + 1)]
    for u, v in zip(it, it):
        adj[u].append(v)
        adj[v].append(u)

    deg = [0] * (n + 1)
    maxd = 0
    for i in range(1, n + 1):
        d = len(adj[i])
        deg[i] = d
        if d > maxd:
            maxd = d

    buckets = [[] for _ in range(maxd + 1)]
    for i in range(1, n + 1):
        d = deg[i]
        if d >= 2:
            buckets[d].append(i)

    cnt = [0] * (n + 1)
    best = 0

    for d in range(maxd, 1, -1):
        for v in buckets[d]:
            for c in adj[v]:
                cnt[c] += 1
                val = 1 + d * cnt[c]
                if val > best:
                    best = val

    sys.stdout.write(str(n - best))

if __name__ == "__main__":
    main()

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Values greater than threshold can never be in an edge (lcm(a,b) >= max(a,b)).
        active = [v for v in nums if v <= threshold]
        isolated = len(nums) - len(active)
        if not active:
            return isolated

        # Map each distinct active value to a DSU index.
        idx = {}
        for v in active:
            if v not in idx:
                idx[v] = len(idx)
        n = len(idx)

        parent = list(range(n))

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        # first_divisor[L] = index of the first active value found dividing L.
        first_divisor = [-1] * (threshold + 1)

        for v in active:
            i = idx[v]
            for L in range(v, threshold + 1, v):
                j = first_divisor[L]
                if j == -1:
                    first_divisor[L] = i
                else:
                    union(i, j)

        roots = set()
        for i in range(n):
            roots.add(find(i))

        return len(roots) + isolated
